var http = require('http');
var idCycleValue = 0;
var ID_CYCLE_MAX = 999;

// ctor
function WebAPI(ip, port, token, name) {
    this.name = name;
    this.header = {
            'Accept': '*/*',
            'Cache-Control': 'no-cache',
            'Content-Type': 'application/json; charset=UTF-8',
            'Pragma': 'no-cache',
            'Connection' : 'close',
            // 'X-Auth-PSK' : token,
            'X-Application-Token' : token,
            // 'X-Request-From' : name,
    };

    this.options = {
            'host' : ip,
            'port' : port,
            'method' : 'POST',
            'headers' : this.header,
            'agent' : false,
    };
};

WebAPI.TIMEOUT = 10000;

