WebAPI.prototype.send = function(par, path, callback, internal) {

    logger.dlog(Logger.VERBOSE, '[WEBAPI] send => ' + par);

    if (!internal) { // undefined or null or false
        this.header['X-Request-From'] = this.name;
    } else {
        delete this.header['X-Request-From'];
    }

    //logger.dlog(Logger.VERBOSE, '[WEBAPI] Caller         => ' + WebAPI.prototype.send.caller);
    logger.dlog(Logger.VERBOSE, '[WEBAPI] X-Request-From => ' + this.header['X-Request-From']);

    idCycleValue++;
    if (idCycleValue > ID_CYCLE_MAX) {
        idCycleValue = 1;
    }
    par = par.replace('"id":0,', '"id":' + idCycleValue + ',');

    this.header['Content-Length'] = par.length;
    this.options['path'] = path;

    // req is an instance of the http.ClientRequest class.
    var req = http.request(this.options, function(res) {
        var body = '';
        res.setEncoding('utf8');
        res.on('data', function(chunk) {
            body += chunk;
        });

        res.on('end', function() {
            // response value
            logger.dlog(Logger.VERBOSE, '[WEBAPI][EVENT] http end');
            logger.dlog(Logger.VERBOSE, '[WEBAPI] @@@@@@@@@@@ send data     => ' + par);
            logger.dlog(Logger.VERBOSE, '[WEBAPI] @@@@@@@@@@@ response data => ' + body);
            if (body != null && body != '') {
              var obj = JSON.parse(body);
              // Process kill for Forbidden occurred
              if (obj.error != undefined) {
                  var timerId;
                  if (obj.error.toString() == "403,Forbidden") {
                      logger.dlog(Logger.WARN, '[WEBAPI][EVENT] Process kill for Forbidden occurred(pid:' + process.pid + ')');
                      process.kill(process.pid, 'SIGTERM');
                  }
              }
              if (obj.auth_url == undefined) {
                  logger.dlog(Logger.VERBOSE, '[WEBAPI][EVENT] http DATA => ' + body);
                  callback(obj);
              } else {
                  logger.rlog(Logger.WARN, '[WEBAPI] >>>>> Pre-Shared Key is not set <<<<<');
                  callback(null);
              }
            }
        });
    });

    req.on('error', function(e) {
        // error
        logger.rlog(Logger.ERROR, '[WEBAPI][EVENT] ClientRequest error (' + e.message + ')');
        callback(JSON.parse('{"error":[1,"WebAPI request error"]}'));
    });

    req.setTimeout(WebAPI.TIMEOUT, function() {
        logger.rlog(Logger.INFO, '[WEBAPI][EVENT] ClientRequest timeout');
        callback(JSON.parse('{"error":[1,"WebAPI request timeout"]}'));
    });
    req.write(par);
    req.end();
};

WebAPI.prototype.setPowerStatus = function(on, callback, internal) {
    //var par = eval('(' + WebAPI.PARAM_SET_POWER_STATUS + ')');
    var par = JSON.parse(WebAPI.PARAM_SET_POWER_STATUS);
    par.params[0].status = on;
    this.send(JSON.stringify(par), '/sony/system', callback, internal);
};

WebAPI.prototype.getPowerStatus = function(callback, internal) {
    this.send(WebAPI.PARAM_GET_POWER_STATUS, '/sony/system', callback, internal);
};

WebAPI.prototype.setPlayContent = function(uri, callback, internal) {
    var par = JSON.parse(WebAPI.PARAM_SET_PLAY_CONTENT);
    par.params[0].uri = uri;
    this.send(JSON.stringify(par), '/sony/avContent', callback, internal);
};

WebAPI.prototype.getPlayingContentInfo = function(callback, internal) {
    this.send(WebAPI.PARAM_GET_PLAYING_CONTENT_INFO, '/sony/avContent', callback, internal);
};

WebAPI.prototype.setPowerSavingMode = function(on, callback, internal) {
    var par = JSON.parse(WebAPI.PARAM_SET_POWER_SAVING_MODE);
    var flag = on ? "pictureOff" : "off";
    par.params[0].mode = flag;
    this.send(JSON.stringify(par), '/sony/system', callback, internal);
};

WebAPI.prototype.setAudioMute = function(on, callback, internal) {
    var par = JSON.parse(WebAPI.PARAM_SET_AUDIO_MUTE);
    par.params[0].status = on;
    this.send(JSON.stringify(par), '/sony/audio', callback, internal);
};

WebAPI.prototype.getPowerSavingMode = function(callback, internal) {
    this.send(WebAPI.PARAM_GET_POWER_SAVING_MODE, '/sony/system', callback, internal);
};

WebAPI.prototype.getVolumeInformation = function(callback, internal) {
    this.send(WebAPI.PARAM_GET_VOLUME_INFORMATION, '/sony/audio', callback, internal);
};

WebAPI.prototype.getCurrentExternalInputsStatus = function(callback, internal) {
    this.send(WebAPI.PARAM_GET_CURRENT_EXTERNAL_INPUTS_STATUS, '/sony/avContent', callback, internal);
};

WebAPI.prototype.setAudioVolume = function(vol, callback, internal) {
    if (isNaN(vol) || !isFinite(vol)) {
        callback(JSON.parse('{"error":[3, "Illegal Argument"]}'));
        return;
    }
    var par = JSON.parse(WebAPI.PARAM_SET_AUDIO_VOLUME);
    par.params[0].volume = vol.toString(10);
    this.send(JSON.stringify(par), '/sony/audio', callback, internal);
};

WebAPI.prototype.getSourceList = function(callback, internal) {
    this.send(WebAPI.PARAM_GET_SOURCE_LIST, '/sony/avContent', callback, internal);
};

WebAPI.prototype.getContentList = function(src, callback, internal) {
    var self = this;
    var getContentCountCallback = function(response) {
        if (response != null && response.error == undefined) {
            var chcount = parseInt(response.result[0].count);
            var stIdx = 0;
            var contentList = [];
            var getContentListCallback = function(response) {
                if (response != null && response.error == undefined) {
                    chcount = chcount - 50;
                    Array.prototype.push.apply(contentList, response.result[0]);
                    if (chcount <= 0) {
                        response.result[0] = contentList;
                        callback(response);
                        return;
                    }
                    stIdx = stIdx + 50;
                    self.getContentListInternal(src, stIdx, getContentListCallback);
                    return;
                } else {
                    callback(response);
                    return;
                }
            };
            self.getContentListInternal(src, stIdx, getContentListCallback);
            return;
        } else {
            callback(response);
            return;
        }
    };
    this.getContentCount(src, getContentCountCallback);
};

