WebAPI.prototype.getContentListInternal = function(src, stIdx, callback, internal) {
    var par = JSON.parse(WebAPI.PARAM_GET_CONTENT_LIST);
    par.params[0].source = src;
    par.params[0].stIdx = stIdx;
    this.send(JSON.stringify(par), '/sony/avContent', callback, internal);
};

WebAPI.prototype.getContentCount = function(src, callback, internal) {
    var par = JSON.parse(WebAPI.PARAM_GET_CONTENT_COUNT);
    par.params[0].source = src;
    this.send(JSON.stringify(par), '/sony/avContent', callback, internal);
};

exports.WebAPI = WebAPI;

exports.createWebAPI = function(ip, port, token, name) {
    return new WebAPI(ip, port, token, name);
};
